ruleHooks.extraMethods:
; Finalizar Romaneio (ação do grid): grava data/hora e operador da finalização
;
; set sc=$$FinalizarRomaneio^WDOMTESTEROM110RG(codEmpresa,codRomaneio)
FinalizarRomaneio(codEmpresa,codRomaneio)	;
$$$VAR
new dados
;
if $get(codRomaneio)="" quit $$$ERROR(10000,"Selecione um romaneio no grid!")
if '$data(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,1)) quit $$$ERROR(10000,"Romaneio "_codRomaneio_" não cadastrado!")
;
set dados=$get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,1))
if $piece(dados,Z,16)'="" quit $$$ERROR(10000,"Romaneio "_codRomaneio_" já está finalizado!")
;
set $piece(dados,Z,16)=$$$horologEmp(codEmpresa)
set $piece(dados,Z,17)=$$VEROP^%CSUTIUD(1)
do $$$SetG(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,1),dados)
;
quit $$$OK
;
; Excluir Romaneio (e os vínculos com o checklist): regra do cadastro
;
; set sc=$$ExcluirRomaneio^WDOMTESTEROM110RG(codEmpresa,codRomaneio)
ExcluirRomaneio(codEmpresa,codRomaneio)	;
$$$VAR
;
quit $$ExcluirRomaneio^WDOMTESTEROM110ARG(codEmpresa,$get(codRomaneio))

ruleHooks.interfaceCode:
; Editar: abre o cadastro do romaneio (item 4) para alterar
;
3500	set sc=$$ObterDadosLinha^%CSW1GRID(CT,%PRG,41,,.DADDET,.CODLIN,.CODREG)
if $$$ISERR(sc) do ME^%CSUTICSP(sc) goto 3000
;
set FLGFUN=1
;
do Show^WDOMTESTEROM110A("3500EX^WDOMTESTEROM110","(CODEMP,$piece(DADDET,Z,3),FLGFUN,.TABALT)")
quit:$$CSP^%CSW1UTI()
;
3500EX	if $data(TABALT) goto 2000
;
goto 3000
;
; Visualizar: abre o cadastro do romaneio só para consulta
;
3610	set sc=$$ObterDadosLinha^%CSW1GRID(CT,%PRG,41,,.DADDET,.CODLIN,.CODREG)
if $$$ISERR(sc) do ME^%CSUTICSP(sc) goto 3000
;
set DISABLE=1
do Show^WDOMTESTEROM110A("3610EX^WDOMTESTEROM110","(CODEMP,$piece(DADDET,Z,3),,,DISABLE)")
quit:$$CSP^%CSW1UTI()
;
3610EX	goto 3000
;
; Finalizar Romaneio
;
3620	set sc=$$ObterDadosLinha^%CSW1GRID(CT,%PRG,41,,.DADDET,.CODLIN,.CODREG)
if $$$ISERR(sc) do ME^%CSUTICSP(sc) goto 3000
;
set sc=$$FinalizarRomaneio^WDOMTESTEROM110RG(CODEMP,$piece(DADDET,Z,3))
if $$$ISERR(sc) do ME^%CSUTICSP(sc) goto 3000
;
do MECABECALHO^%CSW1UTI("Romaneio finalizado!")
;
goto 2000
;
; Excluir
;
3630	set sc=$$ObterDadosLinha^%CSW1GRID(CT,%PRG,41,,.DADDET,.CODLIN,.CODREG)
if $$$ISERR(sc) do ME^%CSUTICSP(sc) goto 3000
;
do SN^%CSUTIUD(,,,2,,"3630SN1^WDOMTESTEROM110")
quit:$$CSP^%CSW1UTI()
;
3630SN1	if SN'="S" goto 3630EX
;
set sc=$$ExcluirRomaneio^WDOMTESTEROM110RG(CODEMP,$piece(DADDET,Z,3))
if $$$ISERR(sc) do ME^%CSUTICSP(sc) goto 3630EX
;
set sc=$$ExcluirLinha^%CSW1GRID2(CT,%PRG,41,,,,CODREG)
;
do MECABECALHO^%CSW1UTI(2)
;
3630EX	goto 3000
